function card(r){const name=text(r.name,'unknown'),[cls,label]=stateOf(r),knownState=['running','stopped','partial'].includes(cls)&&!String(label).toLowerCase().includes('unknown')&&!String(label).toLowerCase().includes('unavailable'),canStart=knownState&&cls==='stopped'&&r.installed!==false,canStop=knownState&&(cls==='running'||cls==='partial'),canRestart=knownState&&cls==='running';return `<article class="card chroot-card" data-name="${escapeText(name)}"><div class="card-heading"><div><p class="eyebrow">${escapeText(r.distro||r.distribution||'Chroot')}</p><h3>${escapeText(name)}</h3></div><span class="badge state ${cls}">${label}</span></div><div class="meta"><div><span>Architecture</span><strong>${escapeText(r.arch||r.architecture)}</strong></div><div><span>Profile</span><strong>${escapeText(r.profile)}</strong></div><div><span>User</span><strong>${escapeText(r.username||r.user)}</strong></div><div><span>Path</span><strong>${escapeText(r.path)}</strong></div></div>${r.details_error?`<p class="notice">Details unavailable: ${escapeText(r.details_error)}</p>`:''}<div class="actions"><button class="button primary" data-action="manage">Manage</button><button class="button secondary" data-action="details">Details</button>${canStart?'<button class="button primary" data-action="start">Start</button>':''}${canStop?'<button class="button secondary" data-action="stop">Stop</button>':''}${canRestart?'<button class="button secondary" data-action="restart">Restart</button>':''}${knownState&&r.installed!==false?'<button class="button secondary" data-action="upgrade">Upgrade</button>':''}<button class="button secondary" data-action="rename">Rename</button><button class="button danger" data-action="remove">Remove</button></div></article>`}
async function loadChroots(){if(busy)return;busy=true;$('refresh-section').disabled=true;$('chroots-list').innerHTML='<div class="card skeleton">Refreshing registered chroots…</div>';try{if(!isAvailable())throw Object.assign(new Error('Open this WebUI from a KernelSU-compatible module manager.'),{code:'WEBUI_BRIDGE_UNAVAILABLE'});const env=await invoke('chrootsList'),baseRows=records(dataOf(env));const rows=[];for(const base of baseRows){let merged={...base};try{const shown=dataOf(await invoke('chrootShow',{name:base.name}));merged={...merged,...(shown.chroot||shown.record||shown)}}catch(e){merged.details_error=e?.code||'DETAILS_UNAVAILABLE'}try{const st=dataOf(await invoke('chrootStatus',{name:base.name}));merged={...merged,...st,status:st}}catch(e){merged.status_error=e?.code||'STATUS_UNAVAILABLE'}rows.push(merged)}chrootContext.rows=rows;$('chroots-summary').innerHTML=`<span class="badge">${rows.length} registered</span><span class="badge">${rows.filter(r=>stateOf(r)[0]==='running').length} running</span>`;$('chroots-list').innerHTML=rows.length?rows.map(card).join(''):'<div class="card empty-state"><p class="eyebrow">No environments yet</p><h3>Create your first chroot</h3><p class="muted">Choose a distribution and let chrootctl validate the install before anything changes.</p><div class="actions"><button class="button primary" type="button" data-empty-create>Create chroot</button></div></div>';const emptyCreate=document.querySelector('[data-empty-create]');if(emptyCreate)emptyCreate.addEventListener('click',()=>showSection('create'));}catch(e){$('chroots-list').innerHTML=`<div class="card"><h3>Unable to load chroots</h3><p class="notice">${escapeText(e?.code||'WEBUI_BACKEND_ERROR')}: ${escapeText(e?.message||'Unknown error')}</p></div>`;}finally{busy=false;$('refresh-section').disabled=false}}
function openChrootManager(name){setChrootContext(name);localStorage.setItem('chrootctl.webui.chroot-context',name);$('context-title').textContent=name;$('context-subtitle').textContent='Manage this chroot';$('chroot-context').classList.remove('hidden');showSection('chroots');detail(name)}
function renderHome(rows=[]){const running=rows.filter(r=>stateOf(r)[0]==='running').length;$('home-chroot-count').textContent=String(rows.length);$('home-running-count').textContent=String(running);$('home-chroot-copy').textContent=rows.length?`${running} running · ${rows.length-running} stopped or unavailable`:'No chroots registered yet';$('home-primary-action').textContent=rows.length?'Open chroots':'Create chroot';$('home-primary-action').dataset.route=rows.length?'chroots':'create'}
async function loadHome(){try{const env=await invoke('chrootsList'),rows=records(dataOf(env));renderHome(rows);chrootContext.rows=rows}catch(e){$('home-chroot-copy').textContent='Chroot summary unavailable';}try{const env=await listSessions();$('home-session-count').textContent=String(records(dataOf(env)).length)}catch(e){$('home-session-count').textContent='—'}try{const env=await listOperations({limit:20});const ops=records(dataOf(env));$('home-job-count').textContent=String(ops.filter(x=>['running','queued','pending'].includes(String(x.state||x.status||'').toLowerCase())).length);$('home-activity').innerHTML=ops.slice(0,3).map(x=>`<div class="activity-row"><strong>${escapeText(x.kind||x.operation||'Operation')}</strong><span>${escapeText(x.state||x.status||'—')}</span></div>`).join('')||'<p class="muted">No recent operations.</p>'}catch(e){$('home-activity').innerHTML='<p class="muted">Activity is unavailable right now.</p>'}}
async function detail(name){const env=await invoke('chrootShow',{name}),d=dataOf(env);let r=d.chroot||d.record||d;try{const st=dataOf(await invoke('chrootStatus',{name}));r={...r,...st,status:st}}catch(e){r={...r,status_error:e?.code||'STATUS_UNAVAILABLE'}}selected=r;$('details-title').textContent=text(r.name,name);const [_,state]=stateOf(r);$('details-body').innerHTML=`<div class="detail-facts"><div><strong>State</strong><br>${escapeText(state)}</div><div><strong>Distribution</strong><br>${escapeText(r.distro||r.distribution)}</div><div><strong>Architecture</strong><br>${escapeText(r.arch||r.architecture)}</div><div><strong>Profile</strong><br>${escapeText(r.profile)}</div><div><strong>User</strong><br>${escapeText(r.username||r.user)}</div><div><strong>Registered path</strong><br>${escapeText(r.path)}</div><div><strong>Installed</strong><br>${r.installed===false?'No':'Yes'}</div></div>`;$('details-dialog').showModal()}
async function mutate(op,payload,success){if(busy)return;busy=true;try{await invoke(op,payload);toast(success);await loadAfterMutation()}catch(e){err(e)}finally{busy=false}}
async function loadAfterMutation(){busy=false;await loadChroots();busy=true}
function lifecyclePreviewBody(d){const blocking=Array.isArray(d.blocking)?d.blocking:[],warnings=Array.isArray(d.warnings)?d.warnings:[];return `<div class="detail-facts"><div><strong>Action</strong><br>${escapeText(d.kind||lifecycleState.action)}</div><div><strong>Chroot</strong><br>${escapeText(d.name||lifecycleState.name)}</div><div><strong>Installed</strong><br>${d.installed===false?'No':'Yes'}</div></div>${blocking.map(x=>`<div class="notice danger-notice">${escapeText(x.message||x.code||x)}</div>`).join('')}${warnings.map(x=>`<div class="notice">${escapeText(x)}</div>`).join('')}`;}
async function reviewLifecycle(name,action){if(lifecycleState.running)return;try{const env=await previewLifecycle(name,action),d=dataOf(env);lifecycleState={name,action,preview:d,running:false,operationId:null};$('lifecycle-title').textContent=`${action[0].toUpperCase()+action.slice(1)} ${name}`;$('lifecycle-review').innerHTML=lifecyclePreviewBody(d);$('lifecycle-run').textContent=action==='remove'?'Remove':action==='upgrade'?'Upgrade':action==='restart'?'Restart':'Start';$('lifecycle-run').classList.toggle('danger',action==='remove');$('lifecycle-run').disabled=d.ok!==true;$('lifecycle-confirm-wrap').classList.toggle('hidden',action!=='remove');$('lifecycle-confirm').value='';if(action==='remove')$('lifecycle-run').disabled=true;$('lifecycle-dialog').showModal()}catch(e){err(e)}}
function lifecycleEvent(event){if(event.operationId)lifecycleState.operationId=String(event.operationId);const p=event.payload||{};$('lifecycle-state').textContent=event.type?.replace(/^operation_/,'')||'Running';$('lifecycle-message').textContent=p.message||p.phase||event.type||'Working…';const pct=Number(p.percent??p.progressPercent);$('lifecycle-progress-bar').style.width=Number.isFinite(pct)?`${Math.max(0,Math.min(100,pct))}%`:'0%';$('lifecycle-cancel').disabled=!lifecycleState.operationId}
