$('chroots-list').addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const article=b.closest('[data-name]'),name=article?.dataset.name,action=b.dataset.action;try{if(action==='manage'){openChrootManager(name);return}else if(action==='details')await detail(name);else if(['start','restart','upgrade'].includes(action))await reviewLifecycle(name,action);else if(action==='stop')await mutate('chrootStop',{name},`${name} stopped`);else if(action==='rename'){selected={name};$('rename-title').textContent=`Rename ${name}`;$('rename-input').value='';$('rename-dialog').showModal()}else if(action==='remove')await reviewLifecycle(name,'remove')}catch(x){err(x)}});
$('rename-form').addEventListener('submit',async e=>{e.preventDefault();const old=selected?.name,next=$('rename-input').value.trim();$('rename-dialog').close();await mutate('chrootRename',{name:old,newName:next},`${old} renamed to ${next}`)});
$('lifecycle-confirm').addEventListener('input',()=>{if(lifecycleState.action==='remove')$('lifecycle-run').disabled=$('lifecycle-confirm').value!==lifecycleState.name||lifecycleState.preview?.ok!==true});
$('lifecycle-run').addEventListener('click',executeLifecycle);
$('lifecycle-cancel').addEventListener('click',async()=>{if(!lifecycleState.operationId)return;try{await cancelOperation(lifecycleState.operationId);$('lifecycle-message').textContent='Cancellation requested…'}catch(e){err(e)}});
$('lifecycle-close').addEventListener('click',()=>{if(!lifecycleState.running)$('lifecycle-dialog').close()});

function optionsHtml(options,selected=''){return (Array.isArray(options)?options:[]).map(o=>{const id=String(o.id??o.ID??''),label=String(o.label??o.Label??id),desc=String(o.description??o.Description??'');return `<option value="${escapeText(id)}" ${id===selected?'selected':''}>${escapeText(label)}${desc?` — ${escapeText(desc)}`:''}</option>`}).join('')}
function defaultID(options,fallback=''){const arr=Array.isArray(options)?options:[];return String(arr.find(x=>x.default)?.id??arr[0]?.id??fallback)}
function setSelect(id,options,preferred=''){const value=(Array.isArray(options)?options:[]).some(o=>String(o.id)===preferred)?preferred:defaultID(options);$(id).innerHTML=optionsHtml(options,value);$(id).value=value;return value}
function catalogChecks(id,entries,selected=[]){const sel=new Set(selected);$(id).innerHTML=(Array.isArray(entries)?entries:[]).length?(entries||[]).map(x=>{const name=String(x.name??''),desc=String(x.description??'');return `<label class="check-row"><input type="checkbox" value="${escapeText(name)}" ${sel.has(name)?'checked':''}><span><strong>${escapeText(name)}</strong>${desc?`<small>${escapeText(desc)}</small>`:''}</span></label>`}).join(''):'<span class="muted">No compatible entries.</span>'}
function selectedChecks(id){return [...$(id).querySelectorAll('input[type=checkbox]:checked')].map(x=>x.value)}
function invalidatePreview(){createState.preview=null;createState.payload=null;$('create-review-actions').classList.add('hidden');$('create-review-body').innerHTML='<span class="muted">Request changed. Review it again before installation.</span>'}
function presetDefaults(id){return {'minimal-server':['minimal','none'],'development':['dev','none'],'desktop-xfce4':['xfce4','xfce4'],'desktop-plasma':['plasma','plasma']}[id]||null}
async function loadCatalogs(distro){const results=await Promise.allSettled([catalog('tools',distro),catalog('addons',distro)]);for(const [i,id] of ['create-tools','create-addons'].entries()){const r=results[i];if(r.status==='fulfilled')catalogChecks(id,dataOf(r.value).entries||[]);else $(id).innerHTML='<span class="muted">Catalog unavailable. Creation can continue without optional entries.</span>'}}
async function loadCreateForm(preserve=false){if(createState.running)return;const generation=++createState.formGeneration;$('create-form-state').textContent='Loading';$('create-review').disabled=true;$('create-form-error').classList.add('hidden');try{const previous=preserve?collectCreatePayload(false):null;const distro=previous?.distro||$('create-distro').value||'ubuntu';const response=await installForm(distro),form=dataOf(response);if(generation!==createState.formGeneration)return;createState.form=form;const defaults=form.defaults||{};const chosenDistro=setSelect('create-distro',form.distros||[],distro||defaults.distro||'ubuntu');const nameWasAuto=!previous||!previous.name||previous.name===createState.lastDistro;$('create-name').value=nameWasAuto?chosenDistro:previous.name;createState.lastDistro=chosenDistro;$('create-username').value=previous?.username||defaults.username||'mike';setSelect('create-arch',form.architectures||[],previous?.arch||defaults.arch||'arm64');const preset=setSelect('create-preset',form.presets||[],previous?.preset||defaults.preset||'minimal-server');let profile=previous?.profile||defaults.profile||'minimal',desktop=previous?.desktop||defaults.desktop||'none';if(!previous){const pd=presetDefaults(preset);if(pd){profile=pd[0];desktop=pd[1]}}setSelect('create-profile',form.profiles||[],profile);setSelect('create-desktop',form.desktops||[],desktop);setSelect('create-mirror',form.mirrors||[],previous?.mirror||defaults.mirror||'auto');$('create-release').value=previous?.release||defaults.release||'';$('create-version').value=previous?.version||defaults.version||'';$('create-resume').checked=previous?.resume===true;$('create-repair').checked=previous?.repair===true;$('create-overwrite').checked=previous?.overwriteExisting===true;await loadCatalogs(chosenDistro);if(generation!==createState.formGeneration)return;updateCrossArchNote();if(previous){for(const [id,values] of [['create-tools',previous.tools],['create-addons',previous.addons]]){const wanted=new Set(values||[]);$(id).querySelectorAll('input[type=checkbox]').forEach(x=>x.checked=wanted.has(x.value))}}$('create-form-state').textContent='Ready';$('create-review').disabled=false;invalidatePreview()}catch(e){if(generation!==createState.formGeneration)return;$('create-form-state').textContent='Unavailable';$('create-review').disabled=true;$('create-form-error').textContent=`${e?.code||'WEBUI_BACKEND_ERROR'}: ${e?.message||'Unable to load install options'}`;$('create-form-error').classList.remove('hidden');}}
function updateCrossArchNote(){const cross=createState.form?.cross_arch||{};const arch=$('create-arch').value;const target=Array.isArray(cross.targets)?cross.targets.find(x=>String(x.arch)===arch):null;let note='';if(target&&!target.ready)note=`${arch} is not executable on this host yet; backend validation may restrict the install to extract-only until qemu/binfmt support is available.`;else if(target&&target.mode==='foreign-ready')note=`${arch} will use foreign-architecture execution support on host ${cross.host_arch||'unknown'}.`;$('cross-arch-note').textContent=note;$('cross-arch-note').classList.toggle('hidden',!note)}
function collectCreatePayload(validate=true){const payload={distro:$('create-distro').value,name:$('create-name').value.trim(),username:$('create-username').value.trim(),arch:$('create-arch').value,preset:$('create-preset').value,profile:$('create-profile').value,desktop:$('create-desktop').value,mirror:$('create-mirror').value,release:$('create-release').value.trim(),version:$('create-version').value.trim(),resume:$('create-resume').checked,repair:$('create-repair').checked,overwriteExisting:$('create-overwrite').checked,tools:selectedChecks('create-tools'),addons:selectedChecks('create-addons')};if(payload.resume&&payload.repair)throw Object.assign(new Error('Resume and Repair cannot both be enabled.'),{code:'WEBUI_INVALID_ARGUMENT'});if(validate&&!$('create-form').checkValidity()){$('create-form').reportValidity();throw Object.assign(new Error('Complete the required fields before review.'),{code:'WEBUI_INVALID_ARGUMENT'})}return payload}
function previewIssues(list,cls='notice'){return (Array.isArray(list)?list:[]).map(x=>`<div class="${cls}">${escapeText(x.message||x)}</div>`).join('')}
function renderPreview(data){const request=data.request||data;const ok=data.ok===true;const warnings=Array.isArray(data.warnings)?data.warnings:[];const blocking=Array.isArray(data.blocking)?data.blocking:[];$('create-review-body').innerHTML=`<div class="review-summary"><span class="badge ${ok?'ready-badge':'error-badge'}">${ok?'Ready':'Blocked'}</span><div class="detail-facts"><div><strong>Name</strong><br>${escapeText(request.name)}</div><div><strong>Distribution</strong><br>${escapeText(request.distro)}</div><div><strong>Architecture</strong><br>${escapeText(request.arch)}</div><div><strong>User</strong><br>${escapeText(request.username)}</div><div><strong>Profile</strong><br>${escapeText(request.profile)}</div><div><strong>Desktop</strong><br>${escapeText(request.desktop)}</div><div><strong>Release</strong><br>${escapeText(request.release,'Default')}</div><div><strong>Version</strong><br>${escapeText(request.version,'Default')}</div><div><strong>Recovery mode</strong><br>${request.repair?'Repair':request.resume?'Resume':'Fresh install'}</div><div><strong>Overwrite existing</strong><br>${(request.overwrite_existing===true||request.overwriteExisting===true)?'Explicitly allowed':'Blocked unless target is empty/managed'}</div><div><strong>Execution mode</strong><br>${escapeText(data.execution_mode)}</div><div><strong>Phases</strong><br>${escapeText((data.phases||[]).join(' → '))}</div><div><strong>Tools</strong><br>${escapeText((request.tools||data.tools||[]).join(', '),'None')}</div><div><strong>Add-ons</strong><br>${escapeText((request.addons||data.addons||[]).join(', '),'None')}</div></div>${previewIssues(blocking,'notice danger-notice')}${warnings.map(x=>`<div class="notice">${escapeText(x)}</div>`).join('')}</div>`;$('create-review-actions').classList.toggle('hidden',!ok)}
async function reviewCreate(){const payload=collectCreatePayload(true);$('create-review').disabled=true;$('create-review-body').innerHTML='<span class="muted">Validating with chrootctl…</span>';$('create-review-actions').classList.add('hidden');try{const response=await previewInstall(payload),data=dataOf(response);createState.preview=data;createState.payload=payload;renderPreview(data)}catch(e){createState.preview=null;createState.payload=null;$('create-review-body').innerHTML=`<div class="notice danger-notice">${escapeText(e?.code||'WEBUI_BACKEND_ERROR')}: ${escapeText(e?.message||'Unable to validate install')}</div>`}finally{$('create-review').disabled=false}}
function progressFromEvent(event){const p=event?.payload||{};if(event.operationId&&!createState.operationId){createState.operationId=String(event.operationId);$('install-cancel').disabled=false}if(event.type==='operation_started'){$('install-state').textContent='Running';$('install-message').textContent='Install started'}if(event.type==='operation_progress'){const pct=Math.max(0,Math.min(100,Number(p.percent??0)||0));$('install-progress-bar').style.width=`${pct}%`;$('install-percent').textContent=`${pct}%`;$('install-message').textContent=text(p.message||p.phase,'Working…');const detail=[p.phase&&`Phase: ${p.phase}`,p.current_path&&`Path: ${p.current_path}`,p.entries&&`Entries: ${p.entries}`].filter(Boolean).join(' · ');$('install-detail').textContent=detail}if(event.type==='operation_succeeded'){$('install-state').textContent='Succeeded';$('install-progress-bar').style.width='100%';$('install-percent').textContent='100%';$('install-message').textContent='Install completed'}if(event.type==='operation_cancelled'){$('install-state').textContent='Cancelled';$('install-message').textContent='Cancellation completed'}if(event.type==='operation_failed'||event.type==='operation_blocked'){$('install-state').textContent=event.type==='operation_blocked'?'Blocked':'Failed'}}
