function fmtBytes(v){const n=Number(v);if(!Number.isFinite(n)||n<0)return '—';const u=['B','KiB','MiB','GiB','TiB'];let x=n,i=0;while(x>=1024&&i<u.length-1){x/=1024;i++}return `${x>=10||i===0?x.toFixed(0):x.toFixed(1)} ${u[i]}`}
function transferPayload(kind){if(kind==='import')return {archive:$('transfer-import-path').value.trim(),name:$('transfer-import-name').value.trim(),conflict:$('transfer-import-conflict').value,importStrategy:$('transfer-import-strategy').value,allowLegacyMetadata:$('transfer-import-legacy').checked,password:$('transfer-import-password').value};return {name:$('transfer-export-name').value,archive:$('transfer-export-path').value.trim(),password:$('transfer-export-password').value}}
function clearTransferPassword(kind){$(kind==='import'?'transfer-import-password':'transfer-export-password').value=''}
function scrubTransferPayload(payload){if(payload&&Object.prototype.hasOwnProperty.call(payload,'password'))payload.password=''}
function localTransferPath(path){return !String(path||'').includes('://')}
function rcloneTransferPath(path){return /^rclone:\/\/[A-Za-z0-9][A-Za-z0-9._-]{0,127}(?:\/[^?#\r\n]*)?$/.test(String(path||''))}
