function renderTransferImportPreview(d){const i=d.inspection||{},meta=i.metadata||{},blocking=Array.isArray(d.blocking)?d.blocking:[],warnings=Array.isArray(d.warnings)?d.warnings:[],integrity=i.integrity_source||i.integritySource||'unknown';$('transfer-import-review').innerHTML=`<div class="detail-facts"><div><strong>Suggested name</strong><br>${escapeText(i.suggested_name||i.suggestedName||'—')}</div><div><strong>Architecture</strong><br>${escapeText(i.arch)}</div><div><strong>Archive</strong><br>${fmtBytes(i.size_bytes||i.sizeBytes)}</div><div><strong>Expanded</strong><br>${fmtBytes(i.extracted_size_bytes||i.extractedSizeBytes)}</div><div><strong>Integrity</strong><br><span class="${i.checksum_verified?'integrity-good':'integrity-warn'}">${escapeText(integrity)}</span></div><div><strong>Metadata fidelity</strong><br>${escapeText(meta.metadata_fidelity||meta.rootfs_metadata_contract||'unknown')}</div><div><strong>Strategy</strong><br>${escapeText(d.importStrategy||$('transfer-import-strategy').value)}</div></div>${previewIssues(blocking,'notice danger-notice')}${warnings.map(x=>`<div class="notice">${escapeText(x)}</div>`).join('')}`;$('transfer-import-actions').classList.toggle('hidden',d.ok!==true)}
function renderTransferExportPreview(d,p){const blocking=Array.isArray(d.blocking)?d.blocking:[],warnings=Array.isArray(d.warnings)?d.warnings:[],archive=d.archive||p.archive||'Managed transfer directory';$('transfer-export-review').innerHTML=`<div class="detail-facts"><div><strong>Chroot</strong><br>${escapeText(p.name)}</div><div><strong>Destination</strong><br>${escapeText(archive)}</div><div><strong>Encryption</strong><br>${p.password?'Enabled':'None'}</div><div><strong>Integrity</strong><br>SHA-256 sidecar after export</div></div>${previewIssues(blocking,'notice danger-notice')}${warnings.map(x=>`<div class="notice">${escapeText(x)}</div>`).join('')}`;$('transfer-export-actions').classList.toggle('hidden',d.ok!==true)}
async function loadTransfer(){try{const env=await invoke('chrootsList'),rows=records(dataOf(env)),button=$('transfer-export-form').querySelector('button'),previous=$('transfer-export-name').value;$('transfer-export-name').innerHTML=rows.map(r=>`<option value="${escapeText(r.name)}">${escapeText(r.name)}</option>`).join('')||'<option value="">No chroots available</option>';if(rows.some(r=>r.name===previous))$('transfer-export-name').value=previous;else{const preferred=preferredChrootName(rows);if(preferred)$('transfer-export-name').value=preferred}button.disabled=!rows.length}catch(e){$('transfer-export-form').querySelector('button').disabled=true;$('transfer-export-review').innerHTML=`<div class="notice danger-notice">${escapeText(e?.code)}: ${escapeText(e?.message)}</div>`}}
$('transfer-import-form').addEventListener('submit',async e=>{e.preventDefault();const p=transferPayload('import');$('transfer-import-actions').classList.add('hidden');$('transfer-import-review').textContent='Inspecting archive and validating import plan…';if(!transferPathAllowed('import',p.archive)){clearTransferPassword('import');scrubTransferPayload(p);$('transfer-import-review').innerHTML='<div class="notice danger-notice">Remote locations must be selected from the Rclone browser. Choose a local archive here or return to Rclone.</div>';return}try{const r=await previewTransferImport(p),d=dataOf(r);transferState.importPreview=d;if(d.ok===true)transferState.importPayload=p;else{scrubTransferPayload(p);clearTransferPassword('import');transferState.importPayload=null}renderTransferImportPreview(d)}catch(e){scrubTransferPayload(p);clearTransferPassword('import');transferState.importPreview=null;transferState.importPayload=null;$('transfer-import-review').innerHTML=`<div class="notice danger-notice">${escapeText(e?.code)}: ${escapeText(e?.message)}</div>`}});
$('transfer-export-form').addEventListener('submit',async e=>{e.preventDefault();const p=transferPayload('export');$('transfer-export-actions').classList.add('hidden');$('transfer-export-review').textContent='Validating export plan…';if(!transferPathAllowed('export',p.archive)){clearTransferPassword('export');scrubTransferPayload(p);$('transfer-export-review').innerHTML='<div class="notice danger-notice">Remote locations must be selected from the Rclone browser. Choose a local destination here or return to Rclone.</div>';return}try{const r=await previewTransferExport(p),d=dataOf(r);transferState.exportPreview=d;if(d.ok===true)transferState.exportPayload=p;else{scrubTransferPayload(p);clearTransferPassword('export');transferState.exportPayload=null}renderTransferExportPreview(d,p)}catch(e){scrubTransferPayload(p);clearTransferPassword('export');transferState.exportPreview=null;transferState.exportPayload=null;$('transfer-export-review').innerHTML=`<div class="notice danger-notice">${escapeText(e?.code)}: ${escapeText(e?.message)}</div>`}});
function transferEvent(event){const p=event?.payload||{};if(event.operationId&&!transferState.operationId){transferState.operationId=String(event.operationId);$('transfer-cancel').disabled=false}if(event.type==='operation_started')$('transfer-op-state').textContent='Running';if(event.type==='operation_progress'){const pct=Math.max(0,Math.min(100,Number(p.percent??0)||0));$('transfer-progress-bar').style.width=`${pct}%`;$('transfer-percent').textContent=`${pct}%`;$('transfer-message').textContent=text(p.message||p.phase,'Working…');const done=p.bytes_done??p.bytesDone,total=p.bytes_total??p.bytesTotal,entries=p.entries??p.entry_count??p.entryCount,current=p.current_path??p.currentPath;const details=[p.phase&&`Phase: ${p.phase}`,done!=null&&`Bytes: ${fmtBytes(done)}${total?` / ${fmtBytes(total)}`:''}`,entries!=null&&`Entries: ${Number(entries).toLocaleString()}`,current&&`Path: ${current}`].filter(Boolean);$('transfer-detail').textContent=details.join(' · ');const free=p.free_bytes??p.freeBytes,expanded=p.expanded_bytes??p.expandedBytes,reserve=p.safety_reserve_bytes??p.safetyReserveBytes,required=p.required_bytes??p.requiredBytes;if(p.phase==='storage'||free!=null){$('transfer-storage').classList.remove('hidden');$('transfer-storage').innerHTML=`<div><span>Free</span><strong>${fmtBytes(free)}</strong></div><div><span>Expanded payload</span><strong>${fmtBytes(expanded)}</strong></div><div><span>Safety reserve</span><strong>${fmtBytes(reserve)}</strong></div><div><span>Required</span><strong>${fmtBytes(required)}</strong></div>`}}if(event.type==='operation_succeeded'){$('transfer-op-state').textContent='Succeeded';$('transfer-progress-bar').style.width='100%';$('transfer-percent').textContent='100%'}if(event.type==='operation_cancelled')$('transfer-op-state').textContent='Cancelled';if(event.type==='operation_failed'||event.type==='operation_blocked')$('transfer-op-state').textContent=event.type==='operation_blocked'?'Blocked':'Failed'}
function renderTransferResult(kind,result){if(!result)return;if(kind==='export'){const archive=result.archive||'—',checksum=result.checksum_path||result.checksumPath||'—';$('transfer-detail').textContent=`Archive: ${archive} · SHA-256: ${checksum}`}else if(result.name){$('transfer-detail').textContent=`Imported chroot: ${result.name}${result.path?` · ${result.path}`:''}`}}
async function executeTransfer(kind,payload,preview){if(transferState.running||!payload||!preview)return;transferState.running=true;transferState.operationId=null;const retryBase={...payload,password:''},hadPassword=Boolean(payload.password);transferState.last={kind,payload:retryBase,needsPassword:hadPassword};$('transfer-op-title').textContent=kind==='import'?'Importing chroot':`Exporting ${payload.name}`;$('transfer-op-state').textContent='Preparing';$('transfer-progress-bar').style.width='0%';$('transfer-percent').textContent='0%';$('transfer-message').textContent='Preparing transfer…';$('transfer-detail').textContent='';$('transfer-storage').classList.add('hidden');$('transfer-op-error').classList.add('hidden');$('transfer-cancel').disabled=true;$('transfer-retry').classList.add('hidden');$('transfer-close').disabled=true;if(!$('transfer-dialog').open)$('transfer-dialog').showModal();try{const outcome=await runTransfer(kind,payload,preview,{onEvent:transferEvent});renderTransferResult(kind,outcome.result);$('transfer-close').disabled=false;$('transfer-cancel').disabled=true;toast(kind==='import'?'Import completed':'Export completed');if(kind==='import'){transferState.importPayload=null;transferState.importRemoteHandoff=false;await loadChroots()}else{transferState.exportPayload=null;transferState.exportRemoteHandoff=false}transferState.last=null}catch(e){$('transfer-op-state').textContent=e?.code==='OPERATION_CANCELLED'?'Cancelled':'Failed';let msg=`${e?.code||'TRANSFER_FAILED'}: ${e?.message||'Transfer failed'}`;if(/space|ENOSPC|no space/i.test(msg)){msg+=' — free space on the target filesystem or remove stale transfer artifacts.';if(kind==='import'&&payload.importStrategy!=='streaming')msg+=' A fresh preview can determine whether Streaming is available.'}$('transfer-op-error').textContent=msg;$('transfer-op-error').classList.remove('hidden');$('transfer-retry').classList.remove('hidden');$('transfer-close').disabled=false;$('transfer-cancel').disabled=true}finally{scrubTransferPayload(payload);clearTransferPassword(kind);transferState.running=false}}
$('transfer-import-run').addEventListener('click',()=>executeTransfer('import',transferState.importPayload,transferState.importPreview));$('transfer-export-run').addEventListener('click',()=>executeTransfer('export',transferState.exportPayload,transferState.exportPreview));$('transfer-cancel').addEventListener('click',async()=>{if(!transferState.operationId)return;$('transfer-cancel').disabled=true;$('transfer-message').textContent='Requesting cancellation…';try{await cancelOperation(transferState.operationId)}catch(e){$('transfer-op-error').textContent=`${e?.code||'CANCEL_FAILED'}: ${e?.message}`;$('transfer-op-error').classList.remove('hidden')}});$('transfer-retry').addEventListener('click',async()=>{const last=transferState.last;if(!last)return;if(last.needsPassword){$('transfer-dialog').close();showSection('transfer');toast('Enter the password again, then review a fresh transfer preview');return}$('transfer-retry').classList.add('hidden');$('transfer-op-error').classList.add('hidden');$('transfer-message').textContent='Refreshing validation before retry…';try{const p={...last.payload},r=last.kind==='import'?await previewTransferImport(p):await previewTransferExport(p),d=dataOf(r);if(d.ok!==true){$('transfer-dialog').close();if(last.kind==='import'){transferState.importPreview=d;renderTransferImportPreview(d)}else{transferState.exportPreview=d;renderTransferExportPreview(d,p)}toast('Retry is blocked by the refreshed transfer preview');return}await executeTransfer(last.kind,p,d)}catch(e){$('transfer-op-error').textContent=`${e?.code||'RETRY_FAILED'}: ${e?.message||'Unable to retry'}`;$('transfer-op-error').classList.remove('hidden');$('transfer-retry').classList.remove('hidden')}});$('transfer-close').addEventListener('click',()=>$('transfer-dialog').close());
['transfer-import-path','transfer-import-name','transfer-import-conflict','transfer-import-strategy','transfer-import-password','transfer-import-legacy'].forEach(id=>$(id).addEventListener('input',()=>{$('transfer-import-actions').classList.add('hidden');scrubTransferPayload(transferState.importPayload);transferState.importPreview=null;transferState.importPayload=null;if(id==='transfer-import-path')transferState.importRemoteHandoff=false}));
