let rcloneState={status:null,location:'',selected:null};
function remoteParent(v){const m=String(v).match(/^(rclone:\/\/[^/]+)(?:\/(.*))?$/);if(!m)return v;const parts=(m[2]||'').split('/').filter(Boolean);parts.pop();return parts.length?`${m[1]}/${parts.join('/')}`:m[1];}
function remoteName(v){const m=String(v).match(/^rclone:\/\/([^/]+)/);return m?.[1]||'';}
function renderRcloneStatus(d){rcloneState.status=d;const remotes=Array.isArray(d.remotes)?d.remotes:[],available=Boolean(d.available);$('rclone-config-form').querySelectorAll('input,button').forEach(el=>{el.disabled=!available});$('rclone-up').disabled=!available;$('rclone-refresh').disabled=!available;$('rclone-remote').disabled=!available;$('rclone-state').textContent=!available?'Unavailable':d.configured?'Ready':'Needs config';$('rclone-state').className=`badge ${d.available&&d.configured?'ready-badge':d.available?'':'error-badge'}`;$('rclone-status').innerHTML=`<div class="storage-facts"><div><span>Runtime</span><strong>${d.available?'Available':'Unavailable'}</strong></div><div><span>Version</span><strong>${escapeText(d.version)}</strong></div><div><span>Configured remotes</span><strong>${remotes.length}</strong></div><div><span>Checked</span><strong>${escapeText(d.checked_at)}</strong></div></div>${!available?`<p class="notice danger-notice"><strong>Rclone is unavailable.</strong><br>${escapeText(readinessReason(d,'The bundled runtime could not be discovered by the backend.'))}<br><small>Open System → Diagnostics to inspect runtime discovery.</small></p>`:d.error?`<p class="notice danger-notice">${escapeText(d.error)}</p>`:''}`;const select=$('rclone-remote');select.innerHTML=remotes.length?remotes.map(n=>`<option value="${escapeText(n)}">${escapeText(n)}</option>`).join(''):'<option value="">No configured remotes</option>';if(remotes.length){const keep=remotes.includes(remoteName(rcloneState.location))?remoteName(rcloneState.location):remotes[0];select.value=keep;if(!rcloneState.location||remoteName(rcloneState.location)!==keep)rcloneState.location=`rclone://${keep}`;browseRclone(rcloneState.location)}else{$('rclone-browser').innerHTML='<p class="muted">Import a valid rclone.conf to configure remotes.</p>';rcloneState.location='';rcloneState.selected=null;updateRemoteSelection();}}
async function loadRclone(){try{const d=dataOf(await rcloneStatus());renderRcloneStatus(d)}catch(e){$('rclone-state').textContent='Unavailable';$('rclone-state').className='badge error-badge';$('rclone-status').innerHTML=`<p class="notice danger-notice"><strong>Rclone status could not be loaded.</strong><br>${escapeText(e?.message||'The backend did not return runtime readiness.')}<br><small>Technical code: ${escapeText(e?.code||'RCLONE_STATUS_UNAVAILABLE')}</small></p>`}}
function updateRemoteSelection(){const x=rcloneState.selected;$('rclone-selection').textContent=x?`${x.is_dir?'Directory':'File'}: ${x.path}`:'Select an archive for remote import or a directory for remote export.';$('rclone-use-import').disabled=!x||x.is_dir||!(/\.tar\.zst(?:\.enc)?$/i.test(x.name));$('rclone-use-export').disabled=!x||!x.is_dir;}
async function browseRclone(location){rcloneState.location=location;rcloneState.selected=null;updateRemoteSelection();$('rclone-path').value=location;$('rclone-location-badge').textContent=remoteName(location)||'—';$('rclone-browser').innerHTML='<p class="muted">Loading remote directory…</p>';try{const d=dataOf(await rcloneList(location)),items=Array.isArray(d.items)?d.items:[];$('rclone-browser').innerHTML=items.length?items.map((x,i)=>`<button type="button" class="remote-row" data-remote-index="${i}"><span><strong>${escapeText(x.name)}</strong><small>${x.is_dir?'Directory':fmtBytes(x.size_bytes)}</small></span><span>${x.is_dir?'›':'Select'}</span></button>`).join(''):'<p class="muted">This directory is empty.</p>';$('rclone-browser').querySelectorAll('[data-remote-index]').forEach(b=>b.addEventListener('click',()=>{const x=items[Number(b.dataset.remoteIndex)];rcloneState.selected=x;updateRemoteSelection();document.querySelectorAll('.remote-row').forEach(r=>r.classList.remove('selected'));b.classList.add('selected')}));rcloneState._items=items}catch(e){$('rclone-browser').innerHTML=`<p class="notice danger-notice">${escapeText(e?.code)}: ${escapeText(e?.message)}</p>`}}
$('rclone-remote').addEventListener('change',e=>{if(e.target.value)browseRclone(`rclone://${e.target.value}`)});$('rclone-up').addEventListener('click',()=>rcloneState.location&&browseRclone(remoteParent(rcloneState.location)));$('rclone-refresh').addEventListener('click',()=>rcloneState.location&&browseRclone(rcloneState.location));
$('rclone-browser').addEventListener('dblclick',e=>{const b=e.target.closest?.('[data-remote-index]');if(!b)return;const x=rcloneState._items?.[Number(b.dataset.remoteIndex)];if(x?.is_dir)browseRclone(x.path)});
$('rclone-config-form').addEventListener('submit',async e=>{e.preventDefault();const path=$('rclone-config-path').value.trim();if(!path)return;try{rcloneState.configOperationId=null;$('rclone-config-form').querySelector('button').disabled=true;$('rclone-config-progress').textContent='Validating staged configuration…';await importRcloneConfig(path,{onEvent:ev=>{if(ev.operationId){rcloneState.configOperationId=String(ev.operationId);$('rclone-config-cancel').disabled=false}const p=ev.payload||{};$('rclone-config-progress').textContent=p.message||p.phase||ev.type||'Working…'}});$('rclone-config-path').value='';$('rclone-config-progress').textContent='Configuration imported; staged credential copy removed.';toast('Rclone configuration imported');await loadRclone()}catch(e){err(e);$('rclone-config-progress').textContent=e?.message||'Rclone configuration import failed'}finally{rcloneState.configOperationId=null;$('rclone-config-cancel').disabled=true;$('rclone-config-form').querySelector('button').disabled=false}});
$('rclone-config-cancel').addEventListener('click',async()=>{if(!rcloneState.configOperationId)return;try{await cancelOperation(rcloneState.configOperationId);$('rclone-config-progress').textContent='Cancellation requested…'}catch(e){err(e)}});
$('rclone-use-import').addEventListener('click',()=>{const x=rcloneState.selected;if(!x)return;scrubTransferPayload(transferState.importPayload);transferState.importPreview=null;transferState.importPayload=null;transferState.importRemoteHandoff=true;$('transfer-import-actions').classList.add('hidden');$('transfer-import-path').value=x.path;$('transfer-import-strategy').value='streaming';showSection('transfer');$('transfer-import-path').focus();toast('Remote archive selected. Review import to continue.')});
$('rclone-use-export').addEventListener('click',async()=>{const x=rcloneState.selected;if(!x?.is_dir)return;let name=$('transfer-export-name').value;try{if(!name){const rows=records(dataOf(await invoke('chrootsList')));name=preferredChrootName(rows)||rows[0]?.name||''}}catch(_){}if(!name){toast('Create or register a chroot before choosing a remote export destination');return}scrubTransferPayload(transferState.exportPayload);transferState.exportPreview=null;transferState.exportPayload=null;transferState.exportRemoteHandoff=true;$('transfer-export-actions').classList.add('hidden');$('transfer-export-path').value=`${x.path.replace(/\/$/,'')}/${encodeURIComponent(name)}.tar.zst`;showSection('transfer');$('transfer-export-path').focus();toast('Remote destination selected. Review export to continue.')});


const operationsState={timer:null,rows:[],selected:null,loading:false};
let lifecycleState={name:null,action:null,preview:null,running:false,operationId:null};
function operationData(r){return r?.data??r?.result??r?.payload??r}
function operationRows(r){const d=operationData(r);return Array.isArray(d)?d:Array.isArray(d?.operations)?d.operations:[]}
function opTime(v){const n=Number(v);if(!Number.isFinite(n)||n<=0)return '—';return new Date(n*1000).toLocaleString()}
function opStateClass(state){return ['failed','blocked','interrupted'].includes(state)?'danger-text':['running','cancelling','queued'].includes(state)?'warning-text':state==='succeeded'?'success-text':''}
function progressFacts(row){const d=row?.progressDetail||{};const done=d.bytes_done??d.bytesDone,total=d.bytes_total??d.bytesTotal,entries=d.entries??d.entry_count??d.entryCount??d.files_done??d.filesDone,entriesTotal=d.entries_total??d.entry_total??d.entryTotal??d.files_total??d.filesTotal,rate=d.rate??d.bytes_per_second??d.bytesPerSecond??d.rate_bytes_per_second??d.rateBytesPerSecond,eta=d.eta??d.eta_seconds??d.etaSeconds;return [row.phase&&`Stage: ${row.phase}`,done!=null&&`Bytes: ${fmtBytes(done)}${total?` / ${fmtBytes(total)}`:''}`,entries!=null&&`Entries: ${Number(entries).toLocaleString()}${entriesTotal!=null?` / ${Number(entriesTotal).toLocaleString()}`:''}`,rate!=null&&`Rate: ${fmtBytes(rate)}/s`,eta!=null&&`ETA: ${typeof eta==='number'?`${Math.max(0,Math.round(eta))}s`:eta}`].filter(Boolean).join(' · ')}
function operationCard(r){const pct=r.progressPercent,active=['queued','running','cancelling'].includes(r.state),needs=['failed','interrupted','orphaned','recovery_needed'].includes(String(r.state||'').toLowerCase());return `<button type="button" class="card operation-row ${needs?'needs-attention':''}" data-operation-id="${esc(r.operationId)}"><div class="card-heading"><div><p class="eyebrow">${esc(r.kind||'operation')}</p><h3>${esc(r.title||r.kind||'Operation')}</h3></div><span class="badge ${opStateClass(r.state)}">${esc(r.state||'unknown')}</span></div><p class="muted">${esc(r.targetName||'Global')} · ${esc(opTime(r.createdAt))}</p><div class="progress-track ${pct==null&&active?'indeterminate':''}"><div class="progress-bar" style="width:${pct==null?0:Math.max(0,Math.min(100,Number(pct)||0))}%"></div></div><p>${esc(r.progressText||'')}</p><p class="muted">${esc(progressFacts(r))}</p>${needs?'<p class="recovery-hint">Open for failure details and recovery actions.</p>':''}</button>`}
function bindOperationCards(host){host?.querySelectorAll('[data-operation-id]').forEach(b=>b.addEventListener('click',()=>openOperation(b.dataset.operationId)))}
function activeJob(r){return ['queued','running','cancelling','failed','interrupted','orphaned','recovery_needed'].includes(String(r.state||'').toLowerCase())}
function renderOperations(){const jobs=$('jobs-list'),activity=$('activity-list');const activeRows=operationsState.rows.filter(activeJob);if(jobs){jobs.innerHTML=activeRows.length?activeRows.map(operationCard).join(''):'<div class="card empty-state"><h3>No active jobs</h3><p class="muted">Background work and jobs needing recovery will appear here.</p></div>';bindOperationCards(jobs)}if(activity){let rows=operationsState.rows;const f=operationsState.activityFilter;if(f==='failed')rows=rows.filter(r=>['failed','interrupted','orphaned','recovery_needed'].includes(String(r.state||'').toLowerCase()));else if(f==='completed')rows=rows.filter(r=>['completed','succeeded','success','cancelled'].includes(String(r.state||'').toLowerCase()));activity.innerHTML=rows.length?rows.map(operationCard).join(''):'<div class="card empty-state"><h3>No matching activity</h3><p class="muted">Operation history will appear here as backend work runs.</p></div>';bindOperationCards(activity)}const activeCount=activeRows.length;if($('operations-summary'))$('operations-summary').textContent=`${activeCount} requiring attention`;if($('activity-summary'))$('activity-summary').textContent=`${operationsState.rows.length} recent`}
async function loadOperations(silent=false){if(operationsState.loading)return;operationsState.loading=true;if(!silent){if($('jobs-list'))$('jobs-list').innerHTML='<div class="card skeleton">Loading active jobs…</div>';if($('activity-list'))$('activity-list').innerHTML='<div class="card skeleton">Loading operation history…</div>';}try{const r=await listOperations(100);operationsState.rows=operationRows(r);renderOperations(); }catch(e){for(const id of ['jobs-list','activity-list'])if($(id))$(id).innerHTML=`<div class="notice danger-notice"><strong>Activity unavailable</strong><p>Backend operation state could not be loaded.</p><details><summary>Technical details</summary><code>${esc(e?.code||'BACKEND_ERROR')}: ${esc(e?.message||'Unable to load operation state')}</code></details></div>`;if($('operations-summary'))$('operations-summary').textContent='Backend unavailable';if($('activity-summary'))$('activity-summary').textContent='Backend unavailable'}finally{operationsState.loading=false}}
function scheduleOperations(){clearInterval(operationsState.timer);operationsState.timer=setInterval(()=>{if(currentSection==='operations')loadOperations(true)},2500)}
async function openOperation(id){try{const r=await getOperation(id),row=operationData(r);operationsState.selected=row;$('operation-detail-title').textContent=row.title||row.kind||'Operation';$('operation-detail-state').textContent=row.state||'unknown';$('operation-detail-meta').textContent=`${row.kind||'operation'} · ${row.targetName||'Global'} · started ${opTime(row.startedAt||row.createdAt)}`;const pct=row.progressPercent;$('operation-detail-progress').style.width=`${pct==null?0:Math.max(0,Math.min(100,Number(pct)||0))}%`;$('operation-detail-progress-track').classList.toggle('indeterminate',pct==null&&['queued','running','cancelling'].includes(row.state));$('operation-detail-message').textContent=row.progressText||'No progress message';$('operation-detail-facts').textContent=progressFacts(row)||'No structured progress metrics reported.';$('operation-detail-error').classList.toggle('hidden',!row.error&&!row.errorCode);$('operation-detail-error').textContent=row.error||row.errorCode||'';$('operation-detail-warnings').textContent=(row.warnings||[]).join('\n');$('operation-detail-warnings').classList.toggle('hidden',!(row.warnings||[]).length);$('operation-detail-cancel').disabled=!['queued','running','cancelling'].includes(row.state);$('operation-detail-retry').classList.toggle('hidden',!['failed','blocked','interrupted','cancelled'].includes(row.state));$('operation-detail-dialog').showModal()}catch(e){toast(`${e?.code||'BACKEND_ERROR'}: ${e?.message||'Unable to load operation'}`)}}
$('operation-detail-cancel').addEventListener('click',async()=>{const r=operationsState.selected;if(!r)return;try{await cancelOperation(r.operationId);toast('Cancellation requested');await openOperation(r.operationId);await loadOperations(true)}catch(e){toast(`${e?.code||'CANCEL_FAILED'}: ${e?.message}`)}})
$('operation-detail-retry').addEventListener('click',async()=>{const r=operationsState.selected;if(!r)return;$('operation-detail-retry').disabled=true;try{await retryOperation(r.operationId);$('operation-detail-dialog').close();toast('Retry started as a new persistent operation');await loadOperations()}catch(e){toast(`${e?.code||'RETRY_FAILED'}: ${e?.message}`)}finally{$('operation-detail-retry').disabled=false}})


function readSettingsPrefs(){try{const raw=localStorage.getItem(SETTINGS_PREF_KEY);const v=raw?JSON.parse(raw):{};return v&&typeof v==='object'?v:{}}catch(_){return {}}}
function preferredChrootName(rows=[]){const preferred=String(readSettingsPrefs().defaultChroot||'');return rows.some(x=>x.name===preferred)?preferred:''}
function saveSettingsPrefs(next){try{localStorage.setItem(SETTINGS_PREF_KEY,JSON.stringify(next))}catch(_){toast('WebUI preference storage is unavailable')};applySettingsPrefs(next)}
function applySettingsPrefs(p=readSettingsPrefs()){document.body.classList.toggle('pref-large-text',p.largeText===true);document.body.classList.toggle('pref-reduce-motion',p.reduceMotion===true);document.body.classList.toggle('pref-compact-nav',p.compactNav===true)}
function settingsSelections(){return [...$('settings-startup-list').querySelectorAll('input[type=checkbox]:checked')].map(x=>x.value)}
function invalidateStartupPreview(){settingsState.preview=null;$('settings-startup-actions').classList.add('hidden');$('settings-startup-review-body').textContent='Startup selection changed. Review the module update again before building.'}
function renderSettingsStartupList(){const current=new Set(Array.isArray(settingsState.module?.startupTargets)?settingsState.module.startupTargets:[]);$('settings-startup-list').innerHTML=settingsState.chroots.length?settingsState.chroots.map(r=>`<label class="check-row"><input type="checkbox" value="${escapeText(r.name)}" ${current.has(r.name)?'checked':''}><span><strong>${escapeText(r.name)}</strong><small>${current.has(r.name)?'Currently starts with module':'Not in current module startup set'}</small></span></label>`).join(''):'<span class="muted">No registered chroots are available as startup targets.</span>';$('settings-startup-list').querySelectorAll('input').forEach(x=>x.addEventListener('change',invalidateStartupPreview));$('settings-startup-state').textContent=current.size?`${current.size} configured`:'None configured'}
function settingFact(label,value){return `<div><dt>${escapeText(label)}</dt><dd>${escapeText(value)}</dd></div>`}
function moduleVersionLabel(m){const st=m?.installedState||{};return st.version?`${st.version}${st.versionCode?` (${st.versionCode})`:''}`:(m?.installed?'Installed':'Not installed')}
function readinessReason(value,fallback){if(!value)return fallback;return value.error||value.reason||value.message||value.detail||value.runtimeReadiness?.reason||value.runtime_readiness?.reason||fallback}
function renderSettingsRuntime(version,runtime,module,rclone){const life=runtime?.lifecycle||{},backend=life.backend||{},active=module?.installedState||{},rr=active.runtimeReadiness||{},remotes=Array.isArray(rclone?.remotes)?rclone.remotes:[],nativeReady=Boolean(module?.ready||rr.ready),rcloneReady=Boolean(rclone?.available);const facts=[settingFact('Backend version',version?.version||version?.backend_version||backend.version||'unknown'),settingFact('Module manager',module?.manager||'unknown'),settingFact('Module',moduleVersionLabel(module)),settingFact('Native runtime',nativeReady?'Ready':`Not ready · ${readinessReason(rr||module,'runtime readiness check failed')}`),settingFact('Rclone',rcloneReady?`${rclone.version||'available'} · ${remotes.length} remote${remotes.length===1?'':'s'}`:`Unavailable · ${readinessReason(rclone,'runtime discovery failed')}`),settingFact('Control mode',life?.mode?.label||runtime?.lifecycle?.state||'unknown')];$('settings-runtime-facts').innerHTML=facts.join('');$('settings-runtime-state').textContent=(nativeReady&&rcloneReady)?'Ready':nativeReady?'Backend ready':'Needs attention';$('settings-runtime-state').className=`badge ${nativeReady?'ready-badge':'error-badge'}`}
async function loadSettingsMounts(){const name=$('settings-mount-target').value;if(!name){$('settings-mount-state').textContent='No chroot';$('settings-mounts').textContent='No registered chroot is available.';return}$('settings-mount-state').textContent='Loading';try{const d=dataOf(await invoke('chrootShow',{name})),r=d.chroot||d.record||d,mounts=String(r.configured_mounts??r.configuredMounts??'').trim();$('settings-mount-state').textContent='Loaded';$('settings-mounts').innerHTML=mounts?`<div class="diagnostic-lines settings-mount-lines">${mounts.split(/,\s*/).filter(Boolean).map(x=>`<div class="log-line"><span class="log-level">BIND</span><span>${escapeText(x)}</span></div>`).join('')}</div>`:'<p class="muted">No enabled media or extra bind mounts are configured for this chroot.</p>'}catch(e){$('settings-mount-state').textContent='Unavailable';$('settings-mounts').innerHTML=`<p class="notice danger-notice">${escapeText(e?.code||'SETTINGS_MOUNTS_UNAVAILABLE')}: ${escapeText(e?.message||'Unable to read target configuration')}</p>`}}
function hydratePreferenceControls(){const p=readSettingsPrefs();$('settings-large-text').checked=p.largeText===true;$('settings-reduce-motion').checked=p.reduceMotion===true;$('settings-compact-nav').checked=p.compactNav===true;const preferred=String(p.defaultChroot||'');if(settingsState.chroots.some(x=>x.name===preferred))$('settings-default-chroot').value=preferred;else if(settingsState.chroots.length)$('settings-default-chroot').value=settingsState.chroots[0].name}
