async function reviewStartupModule(){const targets=settingsSelections();$('settings-startup-review').disabled=true;$('settings-startup-state').textContent='Reviewing';try{const env=await previewModuleBuild(targets),p=dataOf(env);settingsState.preview=p;settingsState.startupTargets=targets;const blocking=Array.isArray(p.blocking)?p.blocking:[],warnings=Array.isArray(p.warnings)?p.warnings:[];$('settings-startup-review-body').innerHTML=`<strong>${blocking.length?'Blocked':'Backend preview ready'}</strong><span>${targets.length?`${targets.length} startup target${targets.length===1?'':'s'}: ${escapeText(targets.join(', '))}`:'No chroots will auto-start.'}</span>${blocking.length?`<span class="danger-text">${escapeText(blocking.join(' · '))}</span>`:''}${warnings.length?`<span>${escapeText(warnings.join(' · '))}</span>`:''}`;$('settings-startup-actions').classList.toggle('hidden',blocking.length>0||p.ok===false);$('settings-startup-state').textContent=blocking.length?'Blocked':'Preview ready'}catch(e){settingsState.preview=null;$('settings-startup-actions').classList.add('hidden');$('settings-startup-state').textContent='Preview failed';$('settings-startup-review-body').innerHTML=`<p class="notice danger-notice">${escapeText(e?.code||'MODULE_PREVIEW_FAILED')}: ${escapeText(e?.message||'Unable to preview module update')}</p>`}finally{$('settings-startup-review').disabled=false}}
