$('settings-default-chroot').addEventListener('change',()=>{const p=readSettingsPrefs();p.defaultChroot=$('settings-default-chroot').value;saveSettingsPrefs(p);if(p.defaultChroot){$('settings-mount-target').value=p.defaultChroot;loadSettingsMounts()}});for(const [id,key] of [['settings-large-text','largeText'],['settings-reduce-motion','reduceMotion'],['settings-compact-nav','compactNav']])$(id).addEventListener('change',()=>{const p=readSettingsPrefs();p[key]=$(id).checked;saveSettingsPrefs(p)});$('settings-mount-target').addEventListener('change',loadSettingsMounts);$('settings-startup-review').addEventListener('click',reviewStartupModule);$('settings-startup-build').addEventListener('click',buildStartupModule);$('settings-open-logs').addEventListener('click',()=>showSection('logs'));$('settings-open-rclone').addEventListener('click',()=>showSection('rclone'));applySettingsPrefs();

function pick(o,...keys){for(const k of keys)if(o?.[k]!==undefined&&o?.[k]!==null)return o[k];return undefined}
function storageFacts(s){const reliable=v=>v===false?' (estimate)':'';return `<div><strong>Rootfs</strong><br>${formatBytes(pick(s,'rootfsBytes','rootfs_bytes'))}${reliable(pick(s,'rootfsBytesReliable','rootfs_bytes_reliable'))}</div><div><strong>Cache</strong><br>${formatBytes(pick(s,'cacheBytes','cache_bytes'))}${reliable(pick(s,'cacheBytesReliable','cache_bytes_reliable'))}</div><div><strong>Snapshots</strong><br>${Number(pick(s,'snapshotCount','snapshot_count'))||0} · ${formatBytes(pick(s,'snapshotBytes','snapshot_bytes'))}${reliable(pick(s,'snapshotBytesReliable','snapshot_bytes_reliable'))}</div><div><strong>Filesystem</strong><br>${formatBytes(pick(s,'freeBytes','free_bytes'))} free / ${formatBytes(pick(s,'totalBytes','total_bytes'))}</div><div><strong>Mount state</strong><br>${escapeText(pick(s,'mountState','mount_state')||'unknown')} · ${Number(pick(s,'mountedCount','mounted_count'))||0}/${Number(pick(s,'mountCount','mount_count'))||0} mounted</div><div><strong>Mount mismatches</strong><br>${Number(pick(s,'mismatchedMountCount','mismatched_mount_count'))||0}</div>`}
function artifactRows(data){const d=dataOf(data);return Array.isArray(d?.items)?d.items:records(d)}
function renderArtifacts(){const rows=storageState.artifacts;$('artifacts-state').textContent=`${rows.length} artifact${rows.length===1?'':'s'}`;$('artifacts-list').innerHTML=rows.length?rows.map(a=>`<article class="card" data-artifact="${escapeText(pick(a,'artifactId','artifact_id')||'')}"><div class="card-heading"><div><p class="eyebrow">${escapeText(a.kind||'artifact')}</p><h3>${escapeText(a.name||'Managed artifact')}</h3></div><span class="badge">${formatBytes(pick(a,'size_bytes','sizeBytes'))}</span></div><div class="meta"><div><span>Path</span><strong>${escapeText(a.path||'—')}</strong></div><div><span>Modified</span><strong>${escapeText(pick(a,'modified_at','modifiedAt')||'—')}</strong></div><div><span>Expires</span><strong>${escapeText(pick(a,'expiresAt','expires_at')||'—')}</strong></div></div><div class="actions"><button class="button danger" data-artifact-clean="${escapeText(a.path||'')}">Clean</button></div></article>`).join(''):'<p class="muted">No managed transfer artifacts.</p>'}
async function loadStorage(){try{if(!storageState.chroots.length){const env=await invoke('chrootsList');storageState.chroots=records(dataOf(env)).filter(x=>x.installed!==false);$('storage-chroot').innerHTML=storageState.chroots.map(x=>`<option value="${escapeText(x.name)}">${escapeText(x.name)}</option>`).join('');applyDefaultChrootToSelect($('storage-chroot'))}const [rootEnv,artifactEnv]=await Promise.all([managedArtifactRoot(),listManagedArtifacts()]);const rd=dataOf(rootEnv);$('artifact-root').value=typeof rd==='string'?rd:(rd?.root||rd?.path||'Managed root');storageState.artifacts=artifactRows(artifactEnv);renderArtifacts();const name=$('storage-chroot').value;if(name){const env=await storageStatus(name),s=dataOf(env);$('storage-summary').innerHTML=storageFacts(s);const mismatch=Number(pick(s,'mismatchedMountCount','mismatched_mount_count'))||0,free=Number(pick(s,'freeBytes','free_bytes'))||0;$('storage-state').textContent=mismatch?'Mount warning':free&&free<1073741824?'Low space':'Healthy'}}catch(e){$('storage-state').textContent='Unavailable';$('storage-summary').innerHTML=`<div class="notice danger-notice">${escapeText(e?.message||'Unable to load storage')}</div>`}}
async function openCleanup(opts){try{storageState.cleanup={opts,preview:null};$('cleanup-dialog').showModal();$('cleanup-state').textContent='Reviewing';$('cleanup-run').disabled=true;$('cleanup-preview').textContent='Requesting authoritative cleanup preview…';const env=await previewArtifactCleanup(opts),d=dataOf(env);storageState.cleanup.preview=d;const blocks=Array.isArray(d.blocking)?d.blocking:[],warnings=Array.isArray(d.warnings)?d.warnings:[];$('cleanup-preview').innerHTML=`<div class="detail-facts"><div><strong>Managed cleanup</strong><br>${opts.deleteAll?'All managed artifacts':escapeText(opts.path||opts.artifactId)}</div></div>${blocks.map(x=>`<div class="notice danger-notice">${escapeText(x.message||x.code||x)}</div>`).join('')}${warnings.map(x=>`<div class="notice">${escapeText(x)}</div>`).join('')}`;$('cleanup-state').textContent=d.ok===true?'Reviewed':'Blocked';$('cleanup-run').disabled=d.ok!==true}catch(e){err(e);$('cleanup-state').textContent='Failed'}}
function cleanupEvent(ev){if(ev.operationId)storageState.operationId=String(ev.operationId);const p=ev.payload||{};$('cleanup-state').textContent=ev.type?.replace(/^operation_/,'')||'Running';$('cleanup-progress-message').textContent=p.message||p.phase||ev.type||'Working…';const pct=Number(p.percent??p.progressPercent);$('cleanup-progress-bar').style.width=Number.isFinite(pct)?`${Math.max(0,Math.min(100,pct))}%`:'0%';$('cleanup-cancel').disabled=!storageState.operationId}
