 const c=await compatibility(),banner=$('compatibility-banner'),state=$('compatibility-state');
 if(!c.ok){banner.classList.remove('hidden');banner.classList.add('danger-notice');$('compatibility-title').textContent='Incompatible root-module backend';$('compatibility-detail').textContent=c.error?.message||'Compatibility discovery failed';state.textContent='Blocked';$('compatibility-summary').innerHTML='<div><strong>Protocol</strong><br>Incompatible or unavailable</div>';$('compatibility-operations').innerHTML='';document.querySelectorAll('button:not([data-section]), select, input').forEach(el=>{if(!el.closest('#compatibility-banner'))el.disabled=true});return false}
