function renderAny(v,depth=0){if(v==null)return '—';if(typeof v!=='object')return escapeText(String(v));if(Array.isArray(v))return v.length?v.slice(0,30).map(x=>`<div class="notice">${renderAny(x,depth+1)}</div>`).join(''):'—';return Object.entries(v).slice(0,30).map(([k,x])=>`<div><strong>${escapeText(k)}</strong><br>${depth<2&&typeof x==='object'?renderAny(x,depth+1):escapeText(typeof x==='object'?JSON.stringify(x):String(x))}</div>`).join('')}
