$('debug-export-review').addEventListener('click',async()=>{try{const d=dataOf(await previewSupportBundle());readinessState.debugPreview=d;$('readiness-actions').innerHTML=maintenancePreviewHtml('Sanitized debug/support evidence',d)+`<div class="actions"><button id="debug-export-run" class="button primary" type="button">Export reviewed evidence</button></div>`;$('debug-export-run').addEventListener('click',async()=>{try{await exportDebugEvidence(readinessState.debugPreview,{onEvent:smokeEvent});toast('Debug evidence exported')}catch(e){err(e)}})}catch(e){err(e)}});
$('maintenance-refresh').addEventListener('click',loadMaintenance);$('support-review').addEventListener('click',()=>reviewMaintenance('support'));$('cleanup-review').addEventListener('click',()=>reviewMaintenance('cleanup'));$('maintenance-run').addEventListener('click',executeMaintenance);$('maintenance-cancel').addEventListener('click',async()=>{if(maintenanceState.operationId)try{await cancelOperation(maintenanceState.operationId)}catch(e){err(e)}});
function repairItems(d){return Array.isArray(d?.items)?d.items:[]}
function renderRepair(){const rows=maintenanceState.repairItems;$('repair-state').textContent=`${rows.length} recommendation${rows.length===1?'':'s'}`;$('repair-list').innerHTML=rows.length?rows.map((x,i)=>`<article class="card"><div class="card-heading"><div><p class="eyebrow">${escapeText(x.severity||'info')} · ${escapeText(x.kind||'repair')}</p><h3>${escapeText(x.name||x.item_id)}</h3></div><input type="checkbox" data-repair-index="${i}" ${maintenanceState.repairSelected.has(x.item_id)?'checked':''}></div><p>${escapeText(x.summary||'')}</p><div class="meta"><div><span>Action</span><strong>${escapeText(x.action||'—')}</strong></div><div><span>Path</span><strong>${escapeText(x.path||'—')}</strong></div><div><span>Expected</span><strong>${escapeText(x.expected_path||'—')}</strong></div></div><p class="muted">${escapeText(x.impact||'')}</p>${Array.isArray(x.diff_lines)?`<pre>${escapeText(x.diff_lines.join('\n'))}</pre>`:''}</article>`).join(''):'<p class="muted">No registry repair recommendations.</p>';$('repair-review').disabled=!maintenanceState.repairSelected.size}
