$('repair-scan').addEventListener('click',scanRepair);$('repair-list').addEventListener('change',e=>{const box=e.target.closest('[data-repair-index]');if(!box)return;const x=maintenanceState.repairItems[Number(box.dataset.repairIndex)];if(!x)return;box.checked?maintenanceState.repairSelected.set(x.item_id,x.action):maintenanceState.repairSelected.delete(x.item_id);$('repair-review').disabled=!maintenanceState.repairSelected.size});
$('repair-review').addEventListener('click',async()=>{try{const decisions=[...maintenanceState.repairSelected].map(([item_id,action])=>({item_id,action})),d=dataOf(await previewRepair(decisions));maintenanceState.action='repair';maintenanceState.preview=d;const selected=Array.isArray(d.selected)?d.selected:[],summary=d.summary||{};$('repair-preview').innerHTML=`<div class="detail-facts"><div><strong>Selected</strong><br>${Number(summary.selected_count)||selected.length}</div><div><strong>Register</strong><br>${Number(summary.register_count)||0}</div><div><strong>Fix path</strong><br>${Number(summary.fix_path_count)||0}</div><div><strong>Remove record</strong><br>${Number(summary.remove_record_count)||0}</div></div>${selected.map(x=>`<div class="notice"><strong>${escapeText(x.name||x.item_id)}</strong> · ${escapeText(x.action)}<br>${escapeText(x.path||'')} ${x.expected_path?`→ ${escapeText(x.expected_path)}`:''}</div>`).join('')}${(summary.warnings||[]).map(x=>`<div class="notice danger-notice">${escapeText(x)}</div>`).join('')}`;$('maintenance-review').innerHTML=$('repair-preview').innerHTML;$('maintenance-run').textContent='Apply reviewed registry repair';$('maintenance-run').disabled=d.ok!==true}catch(e){err(e)}});
function snapshotRows(data){return records(data).filter(x=>x&&x.name)}
function formatBytes(v){const n=Number(v)||0;if(n>=1073741824)return `${(n/1073741824).toFixed(1)} GiB`;if(n>=1048576)return `${(n/1048576).toFixed(1)} MiB`;if(n>=1024)return `${(n/1024).toFixed(1)} KiB`;return `${n} B`}
function renderSnapshots(){const q=$('snapshots-filter').value.trim().toLowerCase(),rows=snapshotsState.rows.filter(s=>!q||String(s.name).toLowerCase().includes(q));$('snapshots-state').textContent=`${rows.length} snapshot${rows.length===1?'':'s'}`;$('snapshots-list').innerHTML=rows.length?rows.map(s=>`<article class="card" data-snapshot="${escapeText(s.name)}"><div class="card-heading"><div><p class="eyebrow">${escapeText(s.kind||'snapshot')}</p><h3>${escapeText(s.name)}</h3></div><span class="badge">${formatBytes(s.size_bytes)}</span></div><div class="meta"><div><span>Created</span><strong>${escapeText(s.created_at||'Unknown')}</strong></div><div><span>Note</span><strong>${escapeText(s.note||'—')}</strong></div><div><span>Authority</span><strong>${escapeText(s.metadata?.authority_state||'Managed')}</strong></div></div><div class="actions"><button class="button secondary" data-snapshot-action="export">Export</button><button class="button danger" data-snapshot-action="restore">Restore</button></div></article>`).join(''):'<p class="muted">No matching snapshots.</p>'}
async function loadSnapshots(){try{if(!snapshotsState.chroots.length){const env=await invoke('chrootsList');snapshotsState.chroots=records(dataOf(env)).filter(x=>x.installed!==false);$('snapshots-chroot').innerHTML=snapshotsState.chroots.map(x=>`<option value="${escapeText(x.name)}">${escapeText(x.name)}</option>`).join('');applyDefaultChrootToSelect($('snapshots-chroot'))}const name=$('snapshots-chroot').value;if(!name){snapshotsState.rows=[];renderSnapshots();return}const env=await listSnapshots(name,100);snapshotsState.rows=snapshotRows(dataOf(env));renderSnapshots()}catch(e){$('snapshots-state').textContent='Unavailable';$('snapshots-list').innerHTML=`<div class="notice danger-notice">${escapeText(e?.message||'Unable to load snapshots')}</div>`}}
function defaultSnapshotName(){const d=new Date(),pad=n=>String(n).padStart(2,'0');return `snapshot-${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}`}
function openSnapshot(action,name=''){snapshotsState.preview=null;snapshotsState.payload=null;snapshotsState.operationId=null;$('snapshot-action').value=action;$('snapshot-name').value=name||defaultSnapshotName();$('snapshot-name').readOnly=action!=='create';$('snapshot-confirm').value='';$('snapshot-archive').value='';$('snapshot-confirm-wrap').classList.toggle('hidden',action!=='restore');$('snapshot-archive-wrap').classList.toggle('hidden',action!=='export');$('snapshot-preview').textContent='Review asks the backend to validate snapshot fidelity and target state.';$('snapshot-progress-message').textContent='';$('snapshot-progress-bar').style.width='0%';$('snapshot-run').disabled=true;$('snapshot-cancel').disabled=true;$('snapshot-dialog-state').textContent='Edit';$('snapshot-dialog-title').textContent=`${action[0].toUpperCase()+action.slice(1)} snapshot`;$('snapshot-dialog').showModal()}
