function snapshotPreviewHtml(d){const blocking=Array.isArray(d.blocking)?d.blocking:[],warnings=Array.isArray(d.warnings)?d.warnings:[];return `<div class="detail-facts"><div><strong>Action</strong><br>${escapeText(d.kind||$('snapshot-action').value)}</div><div><strong>Snapshot</strong><br>${escapeText($('snapshot-name').value)}</div><div><strong>Chroot</strong><br>${escapeText($('snapshots-chroot').value)}</div></div>${blocking.map(x=>`<div class="notice danger-notice">${escapeText(x.message||x.code||x)}</div>`).join('')}${warnings.map(x=>`<div class="notice">${escapeText(x)}</div>`).join('')}`}
