function snapshotEvent(ev){if(ev.operationId)snapshotsState.operationId=String(ev.operationId);const p=ev.payload||{};$('snapshot-dialog-state').textContent=ev.type?.replace(/^operation_/,'')||'Running';$('snapshot-progress-message').textContent=p.message||p.phase||ev.type||'Working…';const pct=Number(p.percent??p.progressPercent);$('snapshot-progress-bar').style.width=Number.isFinite(pct)?`${Math.max(0,Math.min(100,pct))}%`:'0%';$('snapshot-cancel').disabled=!snapshotsState.operationId}
