function bridgeFailureMessage(e){
 const code=e?.code||'WEBUI_BRIDGE_SELF_TEST_FAILED',message=e?.message||'KernelSU bridge readiness check failed';
 if(code==='WEBUI_BRIDGE_UNAVAILABLE')return 'KernelSU WebUI bridge unavailable. Open this module from a compatible KernelSU manager.';
 if(code==='KSU_EXEC_TIMEOUT')return `KernelSU bridge callback timed out. ${message}`;
 if(code==='KSU_ID_PROBE_FAILED')return `KernelSU root-shell probe failed. ${message}`;
 if(code==='KSU_BACKEND_PROBE_FAILED')return `chrootctl backend/version probe failed. ${message}`;
 return `${code}: ${message}`;
}
function renderBridgeFailure(e){
 const chip=$('backend-chip'),label=$('backend-chip-label'),list=$('chroots-list');
 chip.className='status-chip error';label.textContent='Backend unavailable';
 if(list)list.innerHTML=`<div class="card"><h3>Unable to connect to backend</h3><p class="notice danger-notice">${escapeText(bridgeFailureMessage(e))}</p><div class="actions"><button class="button primary" id="bridge-retry">Retry connection</button></div></div>`;
 $('bridge-retry')?.addEventListener('click',()=>bootstrapBackend());
}
async function bootstrapBackend(){
 const chip=$('backend-chip'),label=$('backend-chip-label'),list=$('chroots-list');
 appState.backend='checking';appState.backendError=null;
 chip.className='status-chip';label.textContent='Checking backend…';
 if(list)list.innerHTML='<div class="card skeleton">Checking chrootctl backend…</div>';
 try{
  if(!isAvailable())throw Object.assign(new Error('No supported chrootctl WebUI transport is available.'),{code:'WEBUI_BRIDGE_UNAVAILABLE'});
  label.textContent='Checking backend transport…';
  const probe=await withDeadline(bridgeSelfTest());
  label.textContent='Checking backend capabilities…';
  if(list)list.innerHTML=`<div class="card skeleton">Transport ready (${escapeText(probe?.identity||probe?.transport||'local')}). Checking backend capabilities…</div>`;
  await withDeadline(refreshBackendChip());
  const ok=await withDeadline(loadCompatibility());
  if(!ok)throw Object.assign(new Error('Backend compatibility check did not pass.'),{code:'WEBUI_BACKEND_INCOMPATIBLE'});
  appState.backend='ready';
  showSection(restoredRoute());
 }catch(e){appState.backend='error';appState.backendError={code:e?.code||'WEBUI_BACKEND_ERROR',message:e?.message||'Backend startup failed'};renderBridgeFailure(e)}
}
