async function loadSessions(){try{const [rt,env]=await Promise.all([sessionRuntime(),listSessions()]);const r=dataOf(rt),d=dataOf(env);$('sessions-runtime').textContent=r.ready?'Ready':text(r.status,'Blocked');sessionState.rows=Array.isArray(d)?d:records(d);$('sessions-list').innerHTML=sessionState.rows.length?sessionState.rows.map(x=>`<div class="session-row"><div><strong>${escapeText(x.target||x.name)}</strong><br><small>${escapeText(x.username)} · ${escapeText(x.id)}</small></div><button class="button secondary" data-session-id="${escapeText(x.id)}">Open</button></div>`).join(''):'<p class="muted">No managed sessions.</p>';$('sessions-list').querySelectorAll('[data-session-id]').forEach(b=>b.addEventListener('click',()=>attachSession(b.dataset.sessionId)));}catch(e){$('sessions-list').innerHTML=`<p class="notice danger-notice">${escapeText(e?.code||'SESSION_ERROR')}: ${escapeText(e?.message)}</p>`;}}
async function attachSession(id){sessionState.selected=id;clearInterval(sessionState.timer);$('terminal-title').textContent=id;$('terminal-state').textContent='Connected';$('terminal-reconnect').disabled=false;$('terminal-detach').disabled=false;$('terminal-kill').disabled=false;$('terminal-input').disabled=false;$('terminal-send').disabled=false;await refreshTerminal();sessionState.timer=setInterval(()=>{if(sessionState.selected&&currentSection==='sessions')refreshTerminal()},2000)}
async function refreshTerminal(){if(!sessionState.selected)return;try{const cols=Math.max(40,Math.floor($('terminal-output').clientWidth/8)),rows=Math.max(10,Math.floor($('terminal-output').clientHeight/18));const env=await captureSession(sessionState.selected,500,cols,rows),d=dataOf(env);$('terminal-output').textContent=d.output??'';$('terminal-output').scrollTop=$('terminal-output').scrollHeight;$('terminal-state').textContent='Connected';}catch(e){$('terminal-state').textContent='Recovery needed';$('terminal-output').textContent=`${e?.code||'SESSION_ERROR'}: ${e?.message||'Unable to capture session'}\nUse Reconnect or Refresh sessions.`;}}
$('terminal-send').addEventListener('click',async()=>{if(!sessionState.selected)return;const value=$('terminal-input').value;if(!value)return;try{await inputSession(sessionState.selected,value);$('terminal-input').value='';await refreshTerminal()}catch(e){err(e)}});$('terminal-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('terminal-send').click()}});$('sessions-refresh').addEventListener('click',loadSessions);$('session-create').addEventListener('click',async()=>{try{await createSession($('session-name').value,$('session-user').value);toast('Session ready');await loadSessions()}catch(e){err(e)}});$('terminal-reconnect').addEventListener('click',()=>sessionState.selected&&attachSession(sessionState.selected));$('terminal-detach').addEventListener('click',async()=>{try{await detachSession(sessionState.selected);clearInterval(sessionState.timer);$('terminal-state').textContent='Detached';$('terminal-input').disabled=true;$('terminal-send').disabled=true;toast('Session detached')}catch(e){err(e)}});$('terminal-kill').addEventListener('click',async()=>{if(!sessionState.selected||!confirm('Kill this persistent session?'))return;try{await killSession(sessionState.selected);clearInterval(sessionState.timer);sessionState.selected=null;$('terminal-state').textContent='Killed';$('terminal-input').disabled=true;$('terminal-send').disabled=true;$('terminal-output').textContent='Session killed.';await loadSessions()}catch(e){err(e)}});

document.querySelectorAll('[data-activity-filter]').forEach(b=>b.addEventListener('click',()=>{operationsState.activityFilter=b.dataset.activityFilter;document.querySelectorAll('[data-activity-filter]').forEach(x=>x.classList.toggle('active',x===b));renderOperations()}));
